@-moz-document domain("o2switch.net") {
/* Main Style for background IMG */
.cp-layout-wrapper { 
  background-attachment: fixed !important;
	background-size: 100% !important;
  }
/* Chat bot */ 
typebot-bubble {
  display: none;
}
/* FIX overlay de bouzeux qui cache le menu */
.page-overlay.page-overlay--cover-content-area {
    display: none;
  }
  /* Header */
.header {
    background: transparent !important;
    height: 45px;
}


/* Suppr. marge blanche entre colonnes 1 et 2 */
.cp-layout-wrapper {
    margin-left: clamp(250px,14.8vw,320px);
    background-color: #333;
  }

  .panel.panel-widget {
    border: none !important;
    border-radius: 10px;
    box-shadow: none !important;
    opacity: 0.85 !important;
}

div.container-lg {
   filter: invert(1) hue-rotate(120deg) !important;
}

body[data-app-key="tools"] #boxes .panel {
  opacity:0.8;
  font-size: 12px !important;
  border-radius: 30px;
}
body[data-app-key="tools"] #boxes .panel:hover {
  opacity:0.8;
}

.page-title {
  color:white !important;
}
body {
  color:darkgreen !important;
}

/* Fix Gap at top */
.cp-layout-page {
  margin-top: -70px !important;
}
#cp-main-menu-container {
  width: 40px !important;
  }
.cp-layout-header {
    background: #33333350;
}
  
/* colonne NOM DE LA LUNE */
div #generalInfoSection {
position: sticky;
  top: 0;
  z-index: 1000;
}



/* Taille TXT items */
span.itemTextWrapper.link {
  font-size: 12px;
}
/* TITRES SECTIONS */
.cp-layout-main-content--with-header {
    padding-top: 0px;
}

body[data-app-key="tools"] #boxes .panel-heading {
  background-image: url(data:image/png;base64,);
	background-clip: border-box;
	background-origin: padding-box;
	background-attachment: scroll;
	background-repeat: repeat;
	background-size: auto;
	background-position: left top;
  border-radius: 30px;
   filter: invert(1) hue-rotate(180deg) !important;
  color : white !important;
}

/* Textes des colonnes */
body[data-app-key="tools"] #boxes .panel {
  border-radius: 30px !important;
}
body[data-app-key="tools"] #boxes .panel-heading {
  padding: 5px !important;
  }
}
